    # Found 2 potential faults. Type-codes: 109, 202
    @timeout_decorator.timeout(60)
    def test_15_put_on_role_showsFaults_109_202(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"superadmin\", " + \
            " \"password\" : \"superpass\" " + \
            " } "
        res_superadmin = requests \
                .post(self.baseUrlOfSut + "/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_superadmin =  res_superadmin.json()["token"]
        
        auth_superadmin = "Bearer " + token_superadmin
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"bob\", " + \
            " \"password\" : \"bobpass\" " + \
            " } "
        res_bob = requests \
                .post(self.baseUrlOfSut + "/auth/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_bob =  res_bob.json()["token"]
        
        auth_bob = "Bearer " + token_bob
        
        headers = {}
        headers["Authorization"] = auth_superadmin # superadmin
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"role\" : \"ADMIN\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .put(self.baseUrlOfSut + "/users/bob/role",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 403
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["error"] == "admin role required"
        
        headers = {}
        headers["Authorization"] = auth_bob # bob
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"role\" : \"ADMIN\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_1 = requests \
                .put(self.baseUrlOfSut + "/users/bob/role",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert res_1.json()["username"] == "bob"
        assert res_1.json()["role"] == "ADMIN"
        
        # Fault109. HTTP Violation: no-401-if-no-authenticate.
        # Fault202. Schema Violation: no-401-if-no-auth.
